namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        for (var i = 0; i < 5; i++)
        {
            _notifications.Add(new Notification(
                _nextId++,
                $"Welcome notification #{i + 1}",
                DateTime.UtcNow.AddMinutes(-10 + i)));
        }
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>Simulates an incoming notification (called by background polling).</summary>
    public Notification CreateRandom()
    {
        string[] templates =
        [
            "New comment on your post",
            "Your build succeeded",
            "Deployment to production complete",
            "New follower added",
            "PR review requested",
            "Issue assigned to you",
            "Scheduled maintenance reminder"
        ];

        lock (_lock)
        {
            var n = new Notification(
                _nextId++,
                templates[Random.Shared.Next(templates.Length)],
                DateTime.UtcNow);
            _notifications.Add(n);
            return n;
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationsApp.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Runs during both prerender AND interactive init.
    protected override void OnInitialized()
    {
        // Only load from the service on the very first (prerender) execution.
        // On the second (interactive) call the persisted state is already
        // deserialized into _notifications, so we skip the service call.
        if (_notifications.Count == 0)
        {
            _notifications = NotificationSvc.GetAll();
        }
    }

    // Called once when the component becomes truly interactive (not during prerender).
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        var lastSeenId = _notifications.Count > 0
            ? _notifications.Max(n => n.Id)
            : 0;

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                // Simulate a new notification arriving server-side.
                NotificationSvc.CreateRandom();

                var newer = NotificationSvc.GetSince(lastSeenId);
                if (newer.Count > 0)
                {
                    _notifications.AddRange(newer);
                    lastSeenId = newer.Max(n => n.Id);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

